package pl.edu.pg.eti.kask.aquarium.user.dto;

import pl.edu.pg.eti.kask.aquarium.user.entity.Role;
import pl.edu.pg.eti.kask.aquarium.user.entity.User;

import java.time.LocalDate;
import java.util.UUID;

/**
 * JSON body of a request creating a new user. The identifier is generated by the server.
 */
public record PostUserRequest(String login, String email, LocalDate birthDate, Role role) {

    public User toEntity() {
        return new User(UUID.randomUUID(), login, email, birthDate, role);
    }
}
